def czeroEvaluation (x : L) : C₀(L, 𝕜) →L[𝕜] 𝕜 :=
  LinearMap.mkContinuous (E := C₀(L, 𝕜)) (F := 𝕜) {
    toFun := fun f => f x
    map_add' := fun _ _ => rfl
    map_smul' := fun _ _ => rfl }
    1 (fun f => by simpa only [one_mul] using f.toBCF.norm_coe_le_norm x)

